            color: isMyMessage ? 'white' : 'black',
            padding: '10px 15px',
            borderRadius: '10px',
            maxWidth: '60%',
            wordWrap: 'break-word'
          }}
        >
          <strong>{msg.username}</strong> <small>{msg.time}</small><br />
